        for (int y = p.y + 1; y < 12 && this.map[p.x][y] == 0; y++) {
            l.add(new Point(p.x, y));
        }
        for (int y2 = p.y - 1; y2 >= 0 && this.map[p.x][y2] == 0; y2--) {
            l.add(new Point(p.x, y2));
        }
    }

