package com.lovexy.jisu.view;

    private boolean link(Point p1, Point p2) {
        if (p1.equals(p2)) {
            return false;
        }
        this.path.clear();
        if (this.map[p1.x][p1.y] != this.map[p2.x][p2.y]) {
            return false;
        }
        if (linkD(p1, p2)) {
            this.path.add(p1);
            this.path.add(p2);
            return true;
        }
        Point p = new Point(p1.x, p2.y);
        if (this.map[p.x][p.y] == 0 && linkD(p1, p) && linkD(p, p2)) {
            this.path.add(p1);
            this.path.add(p);
            this.path.add(p2);
            return true;
        }
        Point p3 = new Point(p2.x, p1.y);
        if (this.map[p3.x][p3.y] == 0 && linkD(p1, p3) && linkD(p3, p2)) {
            this.path.add(p1);
            this.path.add(p3);
            this.path.add(p2);
            return true;
        }
        expandX(p1, this.p1E);
        expandX(p2, this.p2E);
        for (Point pt1 : this.p1E) {
            for (Point pt2 : this.p2E) {
                if (pt1.x == pt2.x && linkD(pt1, pt2)) {
                    this.path.add(p1);
                    this.path.add(pt1);
                    this.path.add(pt2);
                    this.path.add(p2);
                    return true;
                }
            }
        }
        expandY(p1, this.p1E);
        expandY(p2, this.p2E);
        for (Point pt12 : this.p1E) {
            for (Point pt22 : this.p2E) {
                if (pt12.y == pt22.y && linkD(pt12, pt22)) {
                    this.path.add(p1);
                    this.path.add(pt12);
                    this.path.add(pt22);
                    this.path.add(p2);
                    return true;
                }
            }
        }
        return false;
    }

package com.lovexy.jisu.view;

    private boolean linkD(Point p1, Point p2) {
        if (p1.x == p2.x) {
            int y1 = Math.min(p1.y, p2.y);
            int y2 = Math.max(p1.y, p2.y);
            boolean flag = true;
            int y = y1 + 1;
            while (true) {
                if (y >= y2) {
                    break;
                }
                if (this.map[p1.x][y] == 0) {
                    y++;
                } else {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                return true;
            }
        }
        if (p1.y == p2.y) {
            int x1 = Math.min(p1.x, p2.x);
            int x2 = Math.max(p1.x, p2.x);
            boolean flag2 = true;
            int x = x1 + 1;
            while (true) {
                if (x >= x2) {
                    break;
                }
                if (this.map[x][p1.y] == 0) {
                    x++;
                } else {
                    flag2 = false;
                    break;
                }
            }
            if (flag2) {
                return true;
            }
        }
        return false;
    }

