    public boolean onTouchEvent(MotionEvent event) {
        int x = (int) event.getX();
        int y = (int) event.getY();
        Point p = screenToindex(x, y);
        if (this.map[p.x][p.y] > 0) {
            if (this.selected.size() == 1) {
                if (link(this.selected.get(0), p)) {
                    this.selected.add(p);
                    drawLine((Point[]) this.path.toArray(new Point[0]));
                    soundPlay.play(1, 0);
                    this.refreshHandler.sleep(500);
                } else {
                    this.selected.clear();
                    this.selected.add(p);
                    soundPlay.play(0, 0);
                    invalidate();
                }
            } else {
                this.selected.add(p);
                soundPlay.play(0, 0);
                invalidate();
            }
        }
        return super.onTouchEvent(event);
    }

